import { useTheme } from '@mui/material/styles';
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import IconButton from '@mui/material/IconButton';
import Typography from '@mui/material/Typography';
import SkipPreviousIcon from '@mui/icons-material/SkipPrevious';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import SkipNextIcon from '@mui/icons-material/SkipNext';
import Duckies from '../images/Duckies-on-Bench.png'

export default function HomeCard() {
  return (
    <Card sx={{ display: 'flex', background: '#061213'}}>
      <Box sx={{ display: 'flex', flexDirection: 'column' }}>
        <CardContent sx={{ width: '50%' }}>
          <Typography component="div" variant="h2" style={{color: 'white'}}>
            Computing Organization for Multicultural Students
          </Typography>
          <Typography
            variant="subtitle1"
            component="div"
            sx={{ color: 'white' }}
          >
            Lorem ipsum dolor sit amet, consectetur adipiscing elit. Duis ac orci sed purus pellentesque cursus ut nec leo. Phasellus at risus quis ante auctor facilisis. Fusce iaculis leo eget dui finibus, volutpat tincidunt erat euismod. Donec accumsan eget ligula at interdum. Lorem ipsum dolor sit amet, consectetur adipiscing elit.
          </Typography>
        </CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', pl: 1, pb: 1 }}>
        </Box>
      </Box>
      <CardMedia
        component="img"
        sx={{ width: '50%' }}
        image={Duckies}
        alt="Live from space album cover"
      />
    </Card>
  );
}
